INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Kundenbeziehungen > Kundengespräche > Nachbereiten
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Nachbereitung eines Kundengesprächs abgeschlossen, wenn die Gesprächsnotizen nur intern gespeichert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenrückmeldung oder Follow-up fehlt"}, {"text": "Ja", "correct": false, "because": "Nachbereitung umfasst mehr als Speicherung"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Nachbereitung eines Kundengesprächs zwingend eine Aktualisierung des CRM-Systems beinhalten?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Prozessen, aber sinnvoll"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Nachbereitung eines Kundengesprächs rechtliche Konsequenzen haben, wenn Vereinbarungen nicht dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Undokumentierte Vereinbarungen sind riskant"}, {"text": "Nein", "correct": false, "because": "Rechtliche Probleme sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es bei der Nachbereitung eines Kundengesprächs ausreichend, nur die positiven Ergebnisse festzuhalten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Kritik und offene Punkte sind relevant"}, {"text": "Ja", "correct": false, "because": "Einseitigkeit verzerrt die Dokumentation"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Nachbereitung eines Kundengesprächs ohne Rückmeldung an den Kunden als vollständig gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Follow-up stärkt die Beziehung"}, {"text": "Ja", "correct": false, "because": "Kundenkommunikation ist essenziell"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme sollte bei der Nachbereitung eines Kundengesprächs zuerst erfolgen?', 2, '[{"text": "Dokumentation der Ergebnisse", "correct": true, "because": "Grundlage für weitere Schritte"}, {"text": "Versand eines Dankesschreibens", "correct": false, "because": "Folgt der Dokumentation"}, {"text": "Planung des nächsten Termins", "correct": false, "because": "Erfordert vorherige Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Nachbereitung eines Kundengesprächs primär?', 3, '[{"text": "Sicherung der Gesprächsergebnisse", "correct": true, "because": "Dokumentation schützt und informiert"}, {"text": "Verbesserung der Verkaufszahlen", "correct": false, "because": "Indirekt, nicht primär"}, {"text": "Reduktion der Gesprächsdauer", "correct": false, "because": "Kein Nachbereitungsziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool ist bei der Nachbereitung eines Kundengesprächs am geeignetsten, um Daten zu verwalten?', 2, '[{"text": "CRM-System", "correct": true, "because": "Zentralisiert Kundeninformationen"}, {"text": "E-Mail-Programm", "correct": false, "because": "Zu unstrukturiert"}, {"text": "Tabellenkalkulation", "correct": false, "because": "Weniger spezialisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information sollte bei der Nachbereitung eines Kundengesprächs unbedingt festgehalten werden?', 2, '[{"text": "Getroffene Vereinbarungen", "correct": true, "because": "Rechtlich und operativ bindend"}, {"text": "Persönliche Vorlieben des Kunden", "correct": false, "because": "Nützlich, aber nicht zwingend"}, {"text": "Dauer des Gesprächs", "correct": false, "because": "Sekundär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die größte Gefahr, wenn die Nachbereitung eines Kundengesprächs unvollständig bleibt?', 2, '[{"text": "Missverständnisse bei Folgegesprächen", "correct": true, "because": "Fehlende Klarheit schadet"}, {"text": "Verlust von Verkaufschancen", "correct": false, "because": "Möglich, aber nicht primär"}, {"text": "Technische Fehler im Projekt", "correct": false, "because": "Nicht direkt verknüpft"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Nachbereitung eines Kundengesprächs?', 4, '[{"text": "Dokumentation der Inhalte", "correct": true, "because": "Grundlage für Nachverfolgung"}, {"text": "Rückmeldung an den Kunden", "correct": true, "because": "Bestätigt Vereinbarungen"}, {"text": "Analyse der Gesprächsergebnisse", "correct": true, "because": "Optimierung für Zukunft"}, {"text": "Erstellung einer Werbekampagne", "correct": false, "because": "Kein Nachbereitungsschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sollten in der Nachbereitung eines Kundengesprächs dokumentiert werden?', 3, '[{"text": "Kundenanforderungen", "correct": true, "because": "Kern des Gesprächs"}, {"text": "Offene Fragen", "correct": true, "because": "Für Follow-up relevant"}, {"text": "Zeitliche Absprachen", "correct": true, "because": "Bindend für Projekte"}, {"text": "Kaffeebestellung", "correct": false, "because": "Irrelevant für Ergebnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch eine unzureichende Nachbereitung eines Kundengesprächs?', 4, '[{"text": "Verlust von Vertrauen", "correct": true, "because": "Kunde fühlt sich ignoriert"}, {"text": "Rechtliche Streitigkeiten", "correct": true, "because": "Undokumentierte Absprachen"}, {"text": "Fehlende Nachverfolgbarkeit", "correct": true, "because": "Informationen gehen verloren"}, {"text": "Geringere Produktqualität", "correct": false, "because": "Nicht direkt betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Abteilungen sollten bei der Nachbereitung eines Kundengesprächs informiert werden?', 3, '[{"text": "Projektmanagement", "correct": true, "because": "Setzt Vereinbarungen um"}, {"text": "Vertrieb", "correct": true, "because": "Verfolgt Kundenstatus"}, {"text": "Entwicklung", "correct": true, "because": "Passt Lösungen an"}, {"text": "Buchhaltung", "correct": false, "because": "Nur bei Abrechnung relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gründliche Nachbereitung eines Kundengesprächs?', 3, '[{"text": "Bessere Kundenbindung", "correct": true, "because": "Kunde fühlt sich ernst genommen"}, {"text": "Klarheit über nächste Schritte", "correct": true, "because": "Vereinbarungen sind dokumentiert"}, {"text": "Verbesserung zukünftiger Gespräche", "correct": true, "because": "Erfahrungen werden genutzt"}, {"text": "Schnellere Produktentwicklung", "correct": false, "because": "Indirekt, nicht primär"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Nachbereitung eines Kundengesprächs dient nur der internen Dokumentation. b) Ein Follow-up mit dem Kunden ist optional.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Nachbereitung umfasst mehr, Follow-up ist sinnvoll"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist zu eng gefasst"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) unterschätzt Follow-up"}, {"text": "Beides stimmt", "correct": false, "because": "Beides ist falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Nachbereitung eines Kundengesprächs sollte Vereinbarungen schriftlich festhalten. b) Eine Analyse der Gesprächsergebnisse ist überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, Analyse wertvoll"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine unvollständige Nachbereitung kann rechtliche Risiken bergen. b) Die Nachbereitung ist nur für den Vertrieb relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rechtliche Risiken ja, mehrere Abteilungen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Nachbereitung eines Kundengesprächs kann die Kundenbindung stärken. b) Eine Rückmeldung an den Kunden ist rechtlich vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kundenbindung ja, Rückmeldung nicht Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Nachbereitung eines Kundengesprächs sollte zeitnah erfolgen. b) Offene Punkte müssen nicht dokumentiert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeitnah ja, offene Punkte relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

